#include <fcntl.h>
#include <stdlib.h>
#include <unistd.h>

int main(void) {
    if (fork() > 0) _exit(0);      /* the original process exits; the child is adopted */
    setsid();                      /* new session: no controlling terminal */
    if (fork() > 0) _exit(0);      /* second fork: this process can never get a terminal again */
    chdir("/");                    /* do not keep a directory busy */
    int fd = open("/dev/null", O_RDWR);
    dup2(fd, 0); dup2(fd, 1); dup2(fd, 2);   /* no terminal I/O */
    for (;;) sleep(60);            /* the "work" */
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>

int main(void) {
    pid_t pid = fork();
    if (pid == 0)
        _exit(0);                  /* the child ends at once */
    printf("parent %d: child %d has exited, but I never call wait()\n", getpid(), pid);
    fflush(stdout);
    sleep(30);
    return 0;
}

#include <stdio.h>
#include <unistd.h>

int main(void) {
    pid_t pid = fork();
    if (pid == 0) {
        sleep(2);                  /* the child outlives its parent */
        printf("child: my parent is now %d\n", getppid());
        return 0;
    }
    printf("parent %d exits first\n", getpid());
    return 0;
}
